import{_ as a,a as e,b as o,c as r,d as i,e as n,f as s}from"./chunks/ind-published.CjzqkIwf.js";import{_ as d,o as l,c as h,ag as c}from"./chunks/framework.CxkNbRKf.js";const u="/nada-documentation/images/ind-create-new-study.png",g="/nada-documentation/images/ind-out-of-sync.png",v=JSON.parse('{"title":"Create an indicator in NADA","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/content/indicators-admin.md","filePath":"admin-guide/content/indicators-admin.md","lastUpdated":1793155456000}'),m={name:"admin-guide/content/indicators-admin.md"};function p(f,t,b,w,k,_){return l(),h("div",null,[...t[0]||(t[0]=[c('<h1 id="create-an-indicator-in-nada" tabindex="-1">Create an indicator in NADA <a class="header-anchor" href="#create-an-indicator-in-nada" aria-label="Permalink to &quot;Create an indicator in NADA&quot;">​</a></h1><p>This page covers the <strong>directly in NADA</strong> workflow: you create the indicator, attach its data structure, upload its data and publish it, all in the NADA admin interface. For the other workflows, see <a href="./indicators.html#choose-a-workflow">Choose a workflow</a>.</p><p>For a guided walk-through with sample files, see the <a href="./indicators-tutorial.html">tutorial</a>.</p><div class="info custom-block"><p class="custom-block-title">Before you begin</p><ul><li><strong>MongoDB</strong> is set up: see <a href="/nada-documentation/installation-guide/installation-mongodb.html">MongoDB setup</a>.</li><li>The indicator&#39;s <strong>data structure</strong> exists in NADA, with its codelists: see <a href="/nada-documentation/admin-guide/web-ui/data-structures.html">Data structures</a>.</li><li>The data is a <strong>CSV file in long format</strong>, with one header per column of the data structure: see <a href="./indicators-concepts.html#data-observations-in-long-format">Key concepts</a>.</li></ul></div><hr><h2 id="_1-create-the-indicator" tabindex="-1">1. Create the indicator <a class="header-anchor" href="#_1-create-the-indicator" aria-label="Permalink to &quot;1. Create the indicator&quot;">​</a></h2><p>Go to <strong>Studies → Manage studies</strong> and click <strong>Add study</strong>. The page offers two ways to create the indicator.</p><h3 id="from-a-metadata-file-recommended" tabindex="-1">From a metadata file (recommended) <a class="header-anchor" href="#from-a-metadata-file-recommended" aria-label="Permalink to &quot;From a metadata file (recommended)&quot;">​</a></h3><p>If you have the indicator&#39;s metadata as a JSON file (exported from the Metadata Editor, or written by a script):</p><ol><li>Under <strong>Import from file</strong>, choose the <strong>Collection</strong> and the <strong>Metadata file</strong>.</li><li>Click <strong>Submit</strong>.</li></ol><p>NADA recognizes a file with a <code>series_description</code> section as a time series. It creates the indicator with the file&#39;s metadata, and opens it. If the file has a <code>data_structure_reference</code>, the indicator is also linked to that data structure.</p><p><img src="'+a+'" alt="Add study, Import from file"></p><p>Turn on <strong>Overwrite if the study already exists?</strong> to replace an indicator that has the same IDNO.</p><h3 id="from-scratch" tabindex="-1">From scratch <a class="header-anchor" href="#from-scratch" aria-label="Permalink to &quot;From scratch&quot;">​</a></h3><ol><li>Under <strong>Create new study</strong>, choose the <strong>Collection</strong>, and set <strong>Select data type</strong> to <strong>Timeseries</strong>.</li><li>Click <strong>Create</strong>.</li></ol><p><img src="'+u+'" alt="Create new study, Timeseries"></p><p>NADA creates an entry titled <em>untitled</em>, with a generated IDNO, and opens it. Enter its metadata in the next step.</p><h3 id="the-indicator-s-page-in-the-admin" tabindex="-1">The indicator&#39;s page in the admin <a class="header-anchor" href="#the-indicator-s-page-in-the-admin" aria-label="Permalink to &quot;The indicator&#39;s page in the admin&quot;">​</a></h3><p>The indicator opens on its <strong>Overview</strong> tab. It shows the <strong>Reference No.</strong> (the IDNO), the years and countries covered, and a <strong>Draft</strong> status: it is not visible in the catalog yet.</p><p><img src="'+e+'" alt="The indicator&#39;s Overview tab"></p><h2 id="_2-enter-or-check-the-metadata" tabindex="-1">2. Enter or check the metadata <a class="header-anchor" href="#_2-enter-or-check-the-metadata" aria-label="Permalink to &quot;2. Enter or check the metadata&quot;">​</a></h2><ol><li>Open the <strong>Metadata</strong> tab.</li><li>Under <strong>Indicator description → Title statement</strong>, enter or check: <ul><li><strong>Primary ID</strong>: the indicator&#39;s unique identifier (its IDNO), such as <code>SI.POV.DDAY</code>.</li><li><strong>Name</strong>: the indicator&#39;s name. It becomes the indicator&#39;s title.</li></ul></li><li>Fill in the other sections you have information for: <strong>Sources, concepts, and methods</strong>, <strong>Geographic and time coverage</strong>, <strong>Description</strong> and the others.</li><li>Click <strong>Save</strong>.</li></ol><p>Use <strong>Required</strong> and <strong>Recommended</strong> above the tree to show only those fields.</p><p><img src="'+o+'" alt="Metadata tab, Title statement"></p><h2 id="_3-attach-the-data-structure" tabindex="-1">3. Attach the data structure <a class="header-anchor" href="#_3-attach-the-data-structure" aria-label="Permalink to &quot;3. Attach the data structure&quot;">​</a></h2><ol><li>Open the <strong>Indicator data</strong> tab.</li><li>Under <strong>Data structure</strong>, pick the data structure in <strong>Select data structure</strong>. If it is already shown, it was linked by the metadata file.</li></ol><p>Two links appear next to the field:</p><ul><li><strong>Open DSD</strong> opens the data structure.</li><li><strong>Download template</strong> downloads an empty CSV with the right headers.</li></ul><p><img src="'+r+'" alt="Indicator data tab with the data structure linked"></p><h2 id="_4-upload-the-data" tabindex="-1">4. Upload the data <a class="header-anchor" href="#_4-upload-the-data" aria-label="Permalink to &quot;4. Upload the data&quot;">​</a></h2><ol><li>Under <strong>Upload data (CSV)</strong>, choose the CSV file.</li><li>Click <strong>Import</strong>.</li></ol><p>The headers must match the column names of the data structure (case does not matter). Columns that are not in the data structure are skipped. Every geography, dimension, time period and observation value column must be present, or the upload is rejected.</p><p>When the upload is done, NADA shows <em>Imported … observation(s)</em> and <strong>Data attached</strong> with the number of rows. NADA also adds a copy of the uploaded file to the indicator&#39;s <strong>Files</strong>.</p><p><img src="'+i+'" alt="Data uploaded"></p><div class="warning custom-block"><p class="custom-block-title">An upload replaces all of the indicator&#39;s data</p><p>If the indicator already has data, NADA asks: <em>This import will replace all existing indicator observations for this study with the rows in your CSV. Continue?</em> Every upload deletes the existing rows first. To add one year, upload the complete file again.</p></div><h2 id="_5-check-the-data" tabindex="-1">5. Check the data <a class="header-anchor" href="#_5-check-the-data" aria-label="Permalink to &quot;5. Check the data&quot;">​</a></h2><p>The tab has two views:</p><ul><li><strong>Data preview</strong>: the uploaded rows, sorted by time (<strong>Time ↑</strong> / <strong>Time ↓</strong>).</li><li><strong>Dimension summaries</strong>: for each coded column, the number of distinct codes and observations. These counts drive the filters on the catalog page. Click <strong>Sync dimension summaries</strong> if they look out of date.</li></ul><p><img src="'+n+'" alt="Dimension summaries"></p><h2 id="_6-add-a-thumbnail-and-publish" tabindex="-1">6. Add a thumbnail and publish <a class="header-anchor" href="#_6-add-a-thumbnail-and-publish" aria-label="Permalink to &quot;6. Add a thumbnail and publish&quot;">​</a></h2><ol><li>On the <strong>Overview</strong> tab, in the <strong>Thumbnail</strong> panel, click the pencil, choose an image and click <strong>Upload</strong>.</li><li>In the <strong>Status</strong> panel, click <strong>Draft</strong>. It changes to <strong>Published</strong>.</li></ol><p><img src="'+s+'" alt="Published indicator"></p><p>Click <strong>Preview study</strong> under the title to open the indicator in the catalog. See <a href="./indicators-frontend.html">Catalog frontend</a>.</p><hr><h2 id="changing-an-indicator-later" tabindex="-1">Changing an indicator later <a class="header-anchor" href="#changing-an-indicator-later" aria-label="Permalink to &quot;Changing an indicator later&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To</th><th>Do this on the Indicator data tab</th></tr></thead><tbody><tr><td>Correct or add data</td><td>Upload the complete file again.</td></tr><tr><td>Remove the data but keep the data structure</td><td>Click <strong>Remove data</strong>.</td></tr><tr><td>Download the data currently stored</td><td>Click <strong>Download data</strong>.</td></tr><tr><td>Detach the data structure</td><td>Click <strong>Remove structure &amp; data</strong>. This deletes the uploaded data too.</td></tr><tr><td>Use another data structure</td><td>Pick it in <strong>Select data structure</strong>. This deletes the uploaded data: upload it again afterwards.</td></tr></tbody></table><h3 id="out-of-sync" tabindex="-1">Out of sync <a class="header-anchor" href="#out-of-sync" aria-label="Permalink to &quot;Out of sync&quot;">​</a></h3><p>When the indicator&#39;s data structure changes, the <strong>Indicator data</strong> tab shows <strong>Out of sync</strong>. Until it is resynced, the indicator&#39;s chart, table and Data API are not available in the public catalog: the public API answers <em>Indicator timeseries data is temporarily unavailable until the catalogue entry is synchronised.</em></p><p>Click <strong>Resync</strong> to update the stored data to the changed data structure. If you changed the data structure&#39;s columns or need new values, upload the data again instead.</p><p><img src="'+g+'" alt="Out of sync"></p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./indicators-frontend.html">Catalog frontend</a>: what users see on the published page</li><li><a href="./indicators-data-api.html">Indicator data API</a>: read the data with scripts</li><li><a href="/nada-documentation/admin-guide/web-ui/data-structures.html">Data structures</a> and <a href="/nada-documentation/admin-guide/web-ui/codelists.html">Codelists</a></li></ul>',53)])])}const C=d(m,[["render",p]]);export{v as __pageData,C as default};
